import{hash as h}from"../daily/puzzles.js";export const perceptionGames=["countrot","trackrot","anglerot","temporot","splitrot"];export function perceptionPuzzle(r,e,n,o=!1){let i=h(`perception:v1:${r}:${e}:${n}:${o}`);const t=()=>{i^=i<<13;i^=i>>>17;i^=i<<5;return(i>>>0)/4294967296},l=0.15+t()*0.7,p=o?(t()<0.5?-1:1)*(1.3+t()):0.1+t()*0.8-l,f=60000/(75+Math.floor(t()*56)),s=t()<0.5,m=r==="countrot"?12+Math.floor(t()*29):r==="trackrot"?reflect(l+p):r==="anglerot"?Math.floor(t()*330)+15+(o?360:0):r==="temporot"?f:o?1.1+Math.floor(t()*8)/10:0.15+Math.floor(t()*14)/20,c=Array.from({length:60},(a,u)=>u);for(let a=c.length-1;a>0;a--){const u=Math.floor(t()*(a+1));[c[a],c[u]]=[c[u],c[a]]}const b=c.slice(0,r==="countrot"?m:0).map((a)=>({x:(a%10+0.3+t()*0.4)/10,y:(Math.floor(a/10)+0.3+t()*0.4)/6,dx:(t()-0.5)*0.04,dy:(t()-0.5)*0.04}));return{target:m,hard:o,right:s,dots:b,start:l,velocity:p,interval:f}}export function reflect(r){const e=(r%2+2)%2;return e<=1?e:2-e}export function perceptionGrade(r,e,n){let o;if(r==="temporot"){if(!Array.isArray(n)||n.length!==8||n.some((t)=>!Number.isFinite(t)))return{points:0,error:1/0};o=n.reduce((t,l,p)=>t+Math.abs(l-(3+(e.hard?0.5:1)+p)*e.interval),0)/8}else{if(typeof n!=="number"||!Number.isFinite(n))return{points:0,error:1/0};o=Math.abs(n-e.target);if(r==="anglerot"&&!e.hard)o=Math.min(o%360,360-o%360)}const i=r==="countrot"?e.target*0.5:r==="trackrot"?0.4:r==="anglerot"?e.hard?180:90:r==="temporot"?e.interval*0.6:0.4;return{points:Math.max(0,Math.round(100*(1-o/i))),error:o}}